import { Difficulty } from "@prisma/client";
import type { AdditionalQuestion } from "./types";

const { EASY, MEDIUM, HARD } = Difficulty;

const D1 = "Splunk Cloud Overview";
const D2 = "Index Management";
const D3 = "User Authentication and Authorization";
const D4 = "Splunk Configuration Files";
const D5 = "Getting Data in Cloud";
const D6 = "Forwarder Management";
const D7 = "Monitor Inputs";
const D8 = "Network and Other Inputs";
const D9 = "Fine-tuning Inputs";
const D10 = "Parsing Phase and Data Preview";
const D11 = "Manipulating Raw Data";
const D12 = "Installing and Managing Apps";
const D13 = "Working with Splunk Cloud Support";

// Aligned to the Splunk Cloud Certified Admin (SPLK-1005) exam blueprint and
// weighted by its published domain percentages. The comment above each group
// names the sub-objective it covers. Configuration snippets use newlines,
// which the quiz renders with white-space: pre-line.
export const splunkCloudAdminQuestions: AdditionalQuestion[] = [
  // 1.1 Splunk Cloud topology
  [D1, EASY, "In Splunk Cloud Platform, which components does Splunk host and operate on the customer's behalf?", "The search heads and indexers that make up the Cloud stack", "The universal forwarders installed on customer servers", "The customer's on-premises deployment server", "The syslog servers in the customer's data center", "Splunk runs the search tier and indexing tier of each Cloud stack. Forwarders, deployment servers, and syslog collectors stay in the customer's environment and are managed by the customer."],
  [D1, MEDIUM, "A company sends data from on-premises servers to Splunk Cloud Platform. Where do its universal forwarders and deployment server run?", "In the customer's environment, managed by the customer", "Inside the Splunk Cloud stack, managed by Splunk", "On the Splunk Cloud search head", "On the Splunk Cloud indexers", "Collection tiers such as forwarders and the deployment server are not part of the Cloud stack. The customer installs and manages them, and they send data to the Cloud indexers."],
  [D1, HARD, "Which path does data from an on-premises universal forwarder typically take in a Splunk Cloud deployment?", "Forwarder, optionally through an intermediate heavy forwarder, to the Cloud indexers over an encrypted connection; users then search it from the Cloud search head", "Forwarder to the Cloud search head, which passes the data on to the indexers", "Forwarder to the deployment server, which uploads the data to Splunk Cloud", "Forwarder to the HTTP Event Collector on the search head, which stores the data locally", "Forwarders send data directly to the indexing tier, sometimes through an intermediate forwarder. The search head only searches the indexed data, and the deployment server manages forwarder configuration rather than relaying data."],
  // 1.2 Tasks managed by the Splunk Cloud admin vs Splunk
  [D1, EASY, "Which task is the responsibility of the customer's Splunk Cloud administrator rather than Splunk?", "Creating users, roles, and indexes", "Patching the operating systems of the indexers", "Upgrading the Splunk Cloud Platform version", "Replacing failed hardware in the indexer cluster", "The customer administers the Splunk-level objects such as users, roles, indexes, inputs, and apps. Splunk handles the underlying infrastructure, operating systems, hardware, and platform upgrades."],
  [D1, MEDIUM, "Which task does Splunk perform for a Splunk Cloud Platform customer?", "Maintaining and upgrading the software that runs the Cloud stack", "Installing universal forwarders on the customer's servers", "Writing props.conf settings for the customer's custom sourcetypes", "Mapping the customer's SAML groups to Splunk roles", "Splunk operates and upgrades the platform itself. Forwarder installation, data onboarding settings, and identity integration are tasks for the customer's administrator."],
  [D1, MEDIUM, "Which role is assigned to the most privileged customer administrator in Splunk Cloud Platform?", "sc_admin", "admin", "power", "can_delete", "Splunk Cloud customers receive the sc_admin role for administration. The full admin role is reserved for Splunk's own operations, and power and can_delete are much narrower roles."],
  // 1.3 Differences between Splunk Cloud and Splunk Enterprise
  [D1, MEDIUM, "An administrator familiar with Splunk Enterprise asks how to edit indexes.conf on the Splunk Cloud indexers. What is the correct answer?", "Indexer configuration files cannot be edited directly; manage indexes through Splunk Web or the Admin Config Service (ACS)", "Connect to the indexers over SSH and edit system/local/indexes.conf", "Push indexes.conf to the Cloud indexers from the on-premises deployment server", "Edit the file from the Splunk Cloud command line", "Splunk Cloud customers have no file-system or CLI access to the stack. Indexes are managed in Splunk Web under Settings > Indexes or through ACS, and a deployment server cannot manage Cloud indexers."],
  [D1, HARD, "Which ability available in Splunk Enterprise is NOT available to customers in Splunk Cloud Platform?", "Command-line and file-system access to the indexers", "Creating custom indexes", "Installing apps", "Creating custom roles", "Customers can still create indexes, install vetted apps, and define roles in Splunk Cloud. What they lose is direct access to the servers, so changes go through Splunk Web, ACS, apps, or Splunk Support."],
  // 1.4 Splunk Cloud Platform experiences
  [D1, EASY, "Splunk Cloud Platform stacks run in one of two experiences. What are they called?", "Victoria and Classic", "Basic and Premium", "Single-instance and Distributed", "Hosted and On-premises", "Each Splunk Cloud Platform stack uses either the Victoria Experience or the Classic Experience. The experience affects how some administrative tasks, such as app installation and inputs, are performed."],
  [D1, MEDIUM, "In the Classic Experience, which separate Splunk-managed component runs modular and scripted inputs that collect data from cloud services?", "The Inputs Data Manager (IDM)", "The deployment server", "The license manager", "The cluster manager", "Classic stacks use an Inputs Data Manager to run API-based and scripted inputs. In the Victoria Experience there is no IDM, and these inputs run on the search tier instead."],

  // 2.1 Define an index
  [D2, EASY, "What is a Splunk index?", "A repository that stores compressed raw data and its index files, and that controls access and retention", "A search-time field that identifies where an event came from", "A configuration file that defines how data is parsed", "A list of the forwarders connected to the deployment", "Indexes hold the data Splunk has processed, as compressed raw data plus index files. Because permissions and retention are set per index, indexes are also the main unit of access control and data lifecycle."],
  [D2, MEDIUM, "Why would an administrator store firewall data and HR application data in separate indexes?", "So each data set can have its own access permissions and retention period", "Because every sourcetype must have its own index", "So the field extractions for each data set run faster", "So both data sets can share one sourcetype", "Access and retention are controlled per index, so data with different audiences or retention needs belongs in different indexes. Many sourcetypes can share one index, so separating by sourcetype is not required."],
  // 2.2 Create indexes in Splunk Cloud
  [D2, EASY, "Where can a Splunk Cloud administrator create a new index without opening a support case?", "Settings > Indexes in Splunk Web", "indexes.conf on the Cloud indexers", "inputs.conf on a universal forwarder", "Settings > Data inputs > Files & Directories", "Splunk Cloud administrators create indexes in Splunk Web under Settings > Indexes, or with the Admin Config Service. Forwarder inputs.conf only names the destination index; it does not create it."],
  [D2, MEDIUM, "When creating an index in Splunk Cloud, which setting controls how long data stays searchable before it is removed or archived?", "Searchable time (retention) in days", "Max raw data size", "Index data type", "App context", "Searchable time defines retention for the index. Max raw data size caps how much data the index holds, which is a size limit rather than a time period."],
  [D2, HARD, "Which Dynamic Data Storage option moves data that has aged out of an index into an Amazon S3 or Google Cloud Storage bucket that the customer owns?", "Dynamic Data Self Storage (DDSS)", "Dynamic Data Active Archive (DDAA)", "Summary indexing", "A frozen directory on the Cloud indexers", "DDSS exports expired data to the customer's own cloud storage bucket. DDAA is the Splunk-managed archive from which data can be restored, and customers have no access to directories on the Cloud indexers."],
  // 2.3 Delete data from an index
  [D2, EASY, "By default, which role must a user hold to run the delete command?", "can_delete", "power", "user", "sc_admin", "The delete command requires the delete_by_keyword capability, which is granted by the can_delete role. Even administrator roles do not have it by default, which protects against accidental data removal."],
  [D2, MEDIUM, "What does the delete command do to the events it matches?", "Marks them as unsearchable without reclaiming disk space", "Removes them from disk immediately", "Moves them to frozen storage", "Re-indexes them into a different index", "delete hides events from future searches but leaves the data on disk until the buckets age out. It cannot be used to recover storage or license usage."],
  [D2, HARD, "An administrator must remove all data from a test index in Splunk Cloud and reclaim the space. What is the appropriate approach?", "Delete the index in Settings > Indexes or with ACS, and recreate it if it is still needed", "Run splunk clean eventdata on the Cloud indexers", "Run a search that pipes every event in the index to delete", "Reduce the index's searchable time to zero days", "Deleting the index removes its data. splunk clean eventdata needs CLI access that Cloud customers do not have, and delete only masks events from searches."],
  // 2.4 Monitor indexing activity
  [D2, MEDIUM, "Which preinstalled app gives Splunk Cloud administrators dashboards for license usage, indexing performance, and forwarder connections?", "Cloud Monitoring Console", "Search & Reporting", "Splunk Secure Gateway", "Splunk Add-on for Unix and Linux", "The Cloud Monitoring Console is the Cloud administrator's view of ingestion, license usage, forwarders, and health. Search & Reporting is for general searching, and the other apps serve different purposes."],
  [D2, MEDIUM, "Which search shows indexing throughput broken down by index from Splunk's internal metrics?", "index=_internal source=*metrics.log group=per_index_thruput", "index=_audit action=search", "index=main sourcetype=splunkd", "| rest /services/authentication/users", "metrics.log records throughput samples, and the per_index_thruput group reports volume for each index. The _audit index records user activity such as searches, not indexing volume."],

  // 3.1 Administer roles
  [D3, EASY, "In Splunk, what is a capability?", "A permission to perform a specific action, such as scheduling searches or editing inputs", "A search-time field extracted from events", "A limit on how much data an index can store", "A tag applied to a group of hosts", "Capabilities are individual permissions such as schedule_search or edit_tcp. Roles bundle capabilities together with index access and search limits."],
  [D3, EASY, "How are capabilities granted to users in Splunk?", "Through the roles assigned to them", "Directly on each user account", "Through the apps they open", "Through the indexes they search", "Capabilities are assigned to roles, and users receive them by being assigned those roles. This keeps permissions consistent for everyone with the same job function."],
  [D3, MEDIUM, "The role web_analyst inherits from the user role. What does a member of web_analyst receive?", "All capabilities and index access of the user role, plus anything added to web_analyst", "Only the capabilities added directly to web_analyst", "The user role's capabilities but not its index access", "The user role's index access but not its capabilities", "Inheritance passes both capabilities and allowed indexes from the parent role to the child role. Settings added to web_analyst build on top of what it inherits."],
  [D3, MEDIUM, "Which role setting limits the indexes that the role's members are permitted to search?", "Indexes (srchIndexesAllowed)", "Default indexes (srchIndexesDefault)", "Search job limit (srchJobsQuota)", "Search filter (srchFilter)", "srchIndexesAllowed defines which indexes a role can search at all. srchIndexesDefault only sets which indexes are searched when a search does not name one, so it grants no access by itself."],
  [D3, MEDIUM, "Members of a role should only ever see events from hosts whose names start with web. Which role setting enforces this?", "A search filter (restriction) such as host=web*", "The role's default app", "The search time window (srchTimeWin)", "The real-time search job limit", "A role search filter is added to every search run by the role's members, limiting the events they can return. The other settings control the landing app, how far back users can search, and concurrency."],
  [D3, HARD, "A user holds two roles. One has the search filter host=web01 and the other has the search filter host=db01. Which events can the user see?", "Events that match either filter, because filters from multiple roles are combined with OR", "Only events that match both filters, because the filters are combined with AND", "Only events allowed by the role that was assigned first", "All events, because conflicting filters cancel each other out", "When a user has several roles with search filters, Splunk combines the filters with OR. Adding a role can therefore widen what a user sees, which matters when designing restrictions."],
  // 3.2 LDAP, Active Directory, and SAML integration
  [D3, EASY, "Which standard lets Splunk Cloud users sign in with single sign-on through a corporate identity provider such as Okta or Microsoft Entra ID?", "SAML 2.0", "RADIUS", "SNMP", "Syslog", "Splunk Cloud supports SAML 2.0 for single sign-on with identity providers. RADIUS is not a Splunk authentication option, and SNMP and syslog are data protocols."],
  [D3, MEDIUM, "After configuring LDAP authentication, how does Splunk decide which roles an LDAP user receives?", "LDAP groups are mapped to Splunk roles", "Each LDAP user automatically receives the sc_admin role", "Roles are copied from the user's Windows profile", "Splunk reads the role names from the user's email address", "The LDAP strategy maps directory groups to Splunk roles. Users receive the roles mapped to the groups they belong to, so access follows directory membership."],
  [D3, MEDIUM, "SAML single sign-on is enabled, but the identity provider is down. How can an administrator sign in with a local Splunk account?", "Append ?loginType=splunk to the Splunk Web login URL", "Clear the browser cache and sign in again", "Use the SAML username with a blank password", "Sign in through the HTTP Event Collector endpoint", "The loginType=splunk parameter shows the native Splunk login page even when SAML is configured. Keeping a working local administrator account is important for exactly this situation."],
  [D3, HARD, "A username exists both as a native Splunk account and in the configured LDAP directory. Which account is used when that user signs in?", "The native Splunk account, because native authentication takes precedence", "The LDAP account, because external authentication always takes precedence", "Whichever account was created most recently", "Neither; Splunk rejects the sign-in because of the conflict", "Splunk checks native accounts before external ones. A local account with the same name as a directory user can therefore unexpectedly override the user's LDAP identity and role mappings."],

  // 4.1 Configuration files and directories
  [D4, EASY, "Why should administrators avoid editing files in an app's default directory?", "Files in default are replaced when the app is upgraded, so changes belong in local", "Files in default are read only at search time", "Files in default are ignored by forwarders", "Files in default have the highest precedence and override everything else", "The default directory ships with the app and is overwritten on upgrade. Customizations go in the app's local directory, which also takes precedence over default."],
  [D4, EASY, "Where should custom configuration changes for an app named my_app be stored?", "$SPLUNK_HOME/etc/apps/my_app/local", "$SPLUNK_HOME/etc/apps/my_app/default", "$SPLUNK_HOME/etc/system/default", "$SPLUNK_HOME/var/lib/splunk/my_app", "The app's local directory holds site-specific changes and survives upgrades. etc/system/default must never be edited, and var/lib/splunk holds index data rather than configuration."],
  [D4, MEDIUM, "Where are a user's private knowledge objects, such as a private saved search, stored?", "$SPLUNK_HOME/etc/users/<username>/<app>/local", "$SPLUNK_HOME/etc/apps/<app>/default", "$SPLUNK_HOME/etc/system/local", "$SPLUNK_HOME/etc/deployment-apps/<app>/local", "Private objects live in the user's directory under the app in which they were created. Sharing an object at app or global level moves it into the app's local directory."],
  [D4, MEDIUM, "Which file defines the sharing permissions for an app's knowledge objects?", "metadata/local.meta, together with metadata/default.meta", "app.conf", "server.conf", "authorize.conf", "Object permissions and export settings are stored in the app's .meta files. app.conf describes the app itself, and authorize.conf defines roles and capabilities rather than object sharing."],
  // 4.2 Configuration precedence
  [D4, MEDIUM, "In the global context used for index-time settings, which directory has the highest precedence?", "$SPLUNK_HOME/etc/system/local", "$SPLUNK_HOME/etc/apps/<app>/local", "$SPLUNK_HOME/etc/apps/<app>/default", "$SPLUNK_HOME/etc/system/default", "In the global context, system/local wins, followed by app local directories, then app default directories, with system/default last. That is why system/default is only a baseline."],
  [D4, HARD, "Apps named app_a and app_b both set the same index-time props.conf attribute in their local directories. Which value is used?", "The value from app_a, because in the global context app names earlier in ASCII order take precedence", "The value from app_b, because the later app name takes precedence", "Whichever app was installed most recently", "Neither; Splunk disables the sourcetype until the conflict is resolved", "When the same setting appears in several apps at the same level in the global context, Splunk prioritizes app directories by ASCII sort order, so app_a wins. Prefixing app names, such as 100_, is a common way to control this."],
  [D4, MEDIUM, "Which command on a forwarder shows the merged inputs configuration and the file that each setting comes from?", "splunk btool inputs list --debug", "splunk list forward-server", "splunk show config inputs", "splunk diag", "btool merges the configuration layers using precedence rules, and --debug shows the source file for each line. splunk diag collects a support bundle rather than displaying merged settings."],
  // 4.3 Index-time vs search-time processing
  [D4, EASY, "Which of these happens at index time?", "Timestamp extraction", "Field aliasing", "Lookups", "Event tagging", "Timestamps are assigned while the data is parsed and written to the index. Field aliases, lookups, and tags are applied when data is searched."],
  [D4, MEDIUM, "Which props.conf setting is applied at search time?", "EXTRACT-<class>", "LINE_BREAKER", "TIME_FORMAT", "SEDCMD-<class>", "EXTRACT- defines a search-time field extraction. LINE_BREAKER, TIME_FORMAT, and SEDCMD all act during parsing, before the data is written to disk."],
  [D4, HARD, "An administrator changes an EXTRACT- field extraction and a TIME_FORMAT setting for the same sourcetype. Which change affects events that are already indexed?", "Only the EXTRACT- change, because index-time settings apply only to newly indexed data", "Only the TIME_FORMAT change, because timestamps are recalculated on every search", "Both changes, because Splunk reprocesses old data after a restart", "Neither change until the data is re-indexed", "Search-time extractions run whenever data is searched, so they apply to old events too. Index-time settings such as TIME_FORMAT are fixed when an event is written, so existing events keep their original timestamps."],

  // 5.1 Forwarder types
  [D5, EASY, "Which forwarder is a lightweight, separately packaged binary designed to collect and send data with minimal resource use?", "Universal forwarder", "Heavy forwarder", "Intermediate search head", "Deployment server", "The universal forwarder is a stripped-down package built to run on production servers with a small footprint. A heavy forwarder is a full Splunk Enterprise instance and uses far more resources."],
  [D5, EASY, "What is a heavy forwarder?", "A full Splunk Enterprise instance configured to forward data, which can parse it before sending", "A universal forwarder with a larger disk queue", "A Splunk Cloud indexer reserved for high-volume data", "A deployment server that also stores data", "A heavy forwarder runs the full Splunk Enterprise software with forwarding enabled. Because it includes the parsing pipeline, it can filter, mask, and route data before it reaches Splunk Cloud."],
  [D5, MEDIUM, "Which forwarder type can drop unwanted events with props.conf and transforms.conf before the data leaves the customer network?", "Heavy forwarder", "Universal forwarder", "Deployment client", "HTTP Event Collector client", "Filtering with transforms requires the parsing pipeline, which a heavy forwarder has. A universal forwarder does not parse most data, so the same transforms placed there would have no effect."],
  [D5, MEDIUM, "An add-on that collects data from a cloud service API needs Python and a setup page in Splunk Web. Which on-premises forwarder type can run it?", "Heavy forwarder", "Universal forwarder", "Either type, because both include Python and Splunk Web", "Neither type, because API inputs only run on indexers", "The heavy forwarder includes Python and Splunk Web, so it can run modular inputs with setup pages. The universal forwarder ships without Python and without a web interface."],
  [D5, MEDIUM, "Why is the universal forwarder usually preferred for collecting data on production application servers?", "It has a small footprint and does not spend resources parsing most data", "It can search data locally before forwarding it", "It is the only forwarder that supports encryption", "It stores a full copy of the data for disaster recovery", "The universal forwarder minimizes CPU, memory, and disk use on the host. Both forwarder types support TLS, and neither is meant to search or archive the data."],
  [D5, HARD, "A universal forwarder monitors CSV files using a sourcetype configured with INDEXED_EXTRACTIONS = csv. Where is this structured data parsed?", "On the universal forwarder, so the sourcetype's props.conf settings must be deployed there", "On the Splunk Cloud indexers, as with all universal forwarder data", "On the Splunk Cloud search head at search time", "On the deployment server before it is forwarded", "Structured data with INDEXED_EXTRACTIONS is an exception to the usual rule: the universal forwarder parses it and the indexers do not parse it again. Props for that sourcetype therefore belong on the forwarder."],
  // 5.2 Role of forwarders
  [D5, EASY, "What is the main role of a forwarder in a Splunk Cloud deployment?", "Collect data from sources and send it to the Splunk Cloud indexers", "Run scheduled searches for users", "Store long-term copies of indexed data", "Authenticate users who sign in to Splunk Web", "Forwarders are the collection tier: they read files, listen on ports, or run inputs, and they send the data to Splunk Cloud. Searching and storage happen in the Cloud stack."],
  [D5, EASY, "Which metadata fields does a forwarder assign to every event it sends?", "host, source, and sourcetype", "user, app, and role", "earliest, latest, and span", "bucket, journal, and tsidx", "Every event carries host, source, and sourcetype default fields, along with its destination index. The other choices are search, role, or index storage terms."],
  [D5, MEDIUM, "Which forwarder behavior keeps data flowing to Splunk Cloud if one of the receiving indexers becomes unavailable?", "Automatic load balancing across the indexers in the target group", "Cloning the data to every indexer", "Buffering all data until the deployment server approves it", "Switching from TCP to UDP", "A forwarder rotates among the receivers in its target group and skips any that are unreachable. Cloning sends full copies to multiple groups and is not how resilience to a single indexer failure is normally achieved."],
  [D5, MEDIUM, "Why do some organizations route many universal forwarders through a few intermediate heavy forwarders before Splunk Cloud?", "To limit outbound connections to a few hosts and to parse, filter, or mask data before it leaves the network", "Because universal forwarders cannot send data over the internet", "Because Splunk Cloud only accepts data from heavy forwarders", "To store a searchable copy of the data on-premises", "An intermediate tier simplifies firewall rules and lets the organization apply parsing-time changes centrally. Universal forwarders can send directly to Splunk Cloud, so the intermediate tier is a design choice rather than a requirement."],
  [D5, HARD, "Data flows from universal forwarders through a heavy forwarder to Splunk Cloud. Where must LINE_BREAKER and TIME_FORMAT settings for this data be deployed?", "On the heavy forwarder, because it parses the data and the Cloud indexers do not parse it again", "On the Splunk Cloud indexers, because indexers always parse incoming data", "On the universal forwarders, because parsing happens at the source", "On the Splunk Cloud search head, because these are search-time settings", "Parsing happens at the first full Splunk Enterprise instance in the path. Data leaves the heavy forwarder already parsed, so Cloud-side line-breaking and timestamp settings are not applied to it."],
  // 5.3 Configure a forwarder to send to Splunk Cloud
  [D5, EASY, "What must be installed on a universal forwarder so it can send data to a Splunk Cloud Platform stack?", "The universal forwarder credentials package downloaded from the Cloud stack", "An HTTP Event Collector token", "The identity provider's SAML metadata file", "The Cloud Monitoring Console app", "The credentials package is an app that contains the stack's forwarding configuration and the certificates needed to connect securely. HEC tokens and SAML metadata serve other purposes."],
  [D5, EASY, "From where does a Splunk Cloud administrator download the universal forwarder credentials package?", "The Universal Forwarder app in Splunk Web on the Cloud stack", "The Splunkbase page for the universal forwarder", "The deployment server's Forwarder Management page", "The Splunk Support portal case page", "Each Cloud stack provides its own credentials package through the Universal Forwarder app in Splunk Web. The package is specific to the stack, so it is not distributed through Splunkbase."],
  [D5, MEDIUM, "Which command installs the credentials package on a Linux universal forwarder?", "splunk install app /tmp/splunkclouduf.spl", "splunk add forward-server /tmp/splunkclouduf.spl", "splunk add monitor /tmp/splunkclouduf.spl", "splunk set deploy-poll /tmp/splunkclouduf.spl", "The package is an app, so it is installed with splunk install app. add forward-server takes a host and port, add monitor creates a file input, and set deploy-poll points the forwarder at a deployment server."],
  [D5, MEDIUM, "What must be done after installing the credentials package on a universal forwarder?", "Restart the forwarder so the new configuration takes effect", "Reboot the Splunk Cloud stack", "Open a support case to activate the package", "Reinstall the forwarder software", "Forwarding configuration is read at startup, so the forwarder must be restarted after the app is installed. Nothing needs to change on the Cloud stack."],
  [D5, MEDIUM, "What does the universal forwarder credentials package configure?", "outputs.conf settings for the Cloud receivers, and the certificates used to authenticate and encrypt the connection", "inputs.conf stanzas for common log files", "The roles and capabilities for forwarder users", "props.conf parsing rules for every sourcetype", "The package handles where and how the forwarder sends data securely. Inputs, parsing rules, and roles still need to be configured separately."],
  [D5, MEDIUM, "Which port do forwarders normally use to send data to Splunk Cloud indexers?", "9997", "8089", "8088", "514", "Splunk-to-Splunk forwarding to Splunk Cloud uses TCP 9997. Port 8089 is the management port, 8088 is the default HEC port in Splunk Enterprise, and 514 is commonly used for syslog."],
  [D5, HARD, "A forwarder has the Splunk Cloud credentials app installed, but an old outputs.conf in etc/system/local still sets defaultGroup to an on-premises indexer group. Where does the data go?", "To the on-premises group, because system/local overrides the defaultGroup set in the app", "To Splunk Cloud, because apps always override system/local", "To both destinations, because each file defines its own default group", "Nowhere, because Splunk refuses to start with conflicting outputs", "In the global context, etc/system/local has the highest precedence, so its defaultGroup wins. Removing or correcting the old file is required before data will reach Splunk Cloud."],
  // 5.4 Test the forwarder connection
  [D5, EASY, "Which command on a forwarder lists its configured receivers and shows which connections are active?", "splunk list forward-server", "splunk list monitor", "splunk show servername", "splunk list deploy-clients", "list forward-server separates active forwards from configured but inactive ones. list monitor shows file inputs, which does not prove that data is reaching Splunk Cloud."],
  [D5, MEDIUM, "Which search in Splunk Cloud confirms that a new forwarder is connected and sending data?", "index=_internal host=<forwarder_hostname>", "index=_audit user=<forwarder_hostname>", "index=main sourcetype=splunkd_ui_access", "| rest /services/apps/local", "Universal forwarders send their own internal logs by default, so seeing them in _internal proves the connection works. The other searches look at user activity or installed apps."],
  [D5, MEDIUM, "A forwarder cannot connect to Splunk Cloud. Which log file on the forwarder should be checked first?", "$SPLUNK_HOME/var/log/splunk/splunkd.log", "$SPLUNK_HOME/var/log/splunk/web_access.log", "$SPLUNK_HOME/etc/system/local/outputs.conf", "/var/log/messages on the Cloud indexers", "splunkd.log records connection attempts, TLS errors, and TcpOutputProc warnings. outputs.conf is configuration rather than a log, and customers cannot read logs directly on the Cloud indexers."],
  [D5, MEDIUM, "A forwarder's internal logs appear in Splunk Cloud, but data from a file it monitors does not. What is a likely cause?", "The inputs.conf stanza names an index that has not been created in Splunk Cloud", "The credentials package is missing", "TCP port 9997 is blocked by the firewall", "The forwarder's clock is set to the wrong time zone", "Arriving internal logs show that the connection and credentials work. The problem is therefore with the input itself, and a destination index that does not exist is a common cause."],
  [D5, HARD, "splunk list forward-server shows the Cloud receivers only under 'Configured but inactive forwards.' What does this indicate, and what should be checked?", "The forwarder cannot establish the connection; check network access to port 9997, DNS resolution, and TLS errors in splunkd.log", "The connection is working but no data has been indexed yet; wait for the next batch", "The forwarder is in maintenance mode; restart the Cloud stack", "The deployment server has disabled forwarding; remove the deployment client", "Inactive means the receivers are configured but no connection is up. Network, name resolution, and certificate problems are the usual causes, and splunkd.log shows the specific error."],
  // 5.5 Optional forwarder settings
  [D5, EASY, "Which outputs.conf setting turns on indexer acknowledgment?", "useACK = true", "compressed = true", "autoLBFrequency = 30", "sslVerifyServerCert = true", "useACK makes the forwarder wait for indexers to confirm that data has been written. The other settings control compression, load-balancing timing, and certificate validation."],
  [D5, EASY, "What does indexer acknowledgment protect against?", "Losing data in transit, because the forwarder keeps data until the indexer confirms it was written", "Duplicate events being indexed", "Unauthorized users searching the data", "Timestamps being extracted incorrectly", "With acknowledgment, the forwarder resends data that was not confirmed, closing gaps caused by connection drops. It can actually introduce occasional duplicates, so it does not prevent them."],
  [D5, MEDIUM, "What does the autoLBFrequency setting in outputs.conf control?", "How often, in seconds, the forwarder switches to another receiver in the target group", "How many receivers the forwarder may connect to at once", "How long the forwarder waits for an acknowledgment", "How frequently the forwarder checks in with the deployment server", "Load-balanced forwarders change receivers on an interval set by autoLBFrequency, which spreads data across indexers. Deployment server check-ins are configured in deploymentclient.conf instead."],
  [D5, MEDIUM, "What is a trade-off of enabling useACK = true on a forwarder?", "Some events may be indexed twice if acknowledgments are lost and the data is resent", "Data is no longer encrypted in transit", "The forwarder stops load balancing", "Events lose their source and sourcetype metadata", "When an acknowledgment does not arrive, the forwarder resends the data, which can create duplicates. Encryption, load balancing, and metadata are unaffected."],
  [D5, MEDIUM, "Which outputs.conf setting makes a forwarder switch receivers after sending a set amount of data, in addition to switching on a time interval?", "autoLBVolume", "maxQueueSize", "connectionTimeout", "forceTimebasedAutoLB", "autoLBVolume sets a byte threshold that triggers a switch to another receiver, which helps balance high-volume forwarders. maxQueueSize sizes the output queue, and connectionTimeout limits connection attempts."],
  [D5, HARD, "A universal forwarder switches receivers in the middle of a multiline event, splitting it between indexers. Which settings in the forwarder's props.conf prevent this?", "EVENT_BREAKER_ENABLE = true and EVENT_BREAKER = <regex>", "SHOULD_LINEMERGE = true and BREAK_ONLY_BEFORE_DATE = true", "LINE_BREAKER = ([\\r\\n]+) and TRUNCATE = 0", "useACK = true and autoLBVolume = 0", "The event breaker tells the universal forwarder where events end so it switches receivers only on an event boundary. SHOULD_LINEMERGE and LINE_BREAKER are parsing settings that a universal forwarder does not apply to unstructured data."],
  [D5, HARD, "What does this forwarder outputs.conf configuration do?\n[tcpout]\ndefaultGroup = splunkcloud\n[tcpout:splunkcloud]\nserver = inputs1.example.splunkcloud.com:9997, inputs2.example.splunkcloud.com:9997\nuseACK = true", "Load-balances data across both receivers and waits for acknowledgment before discarding sent data", "Sends a full copy of every event to each receiver", "Sends data only to inputs1 and uses inputs2 only if inputs1 fails permanently", "Sends acknowledgments from the forwarder to the receivers", "Several servers in one target group are load-balanced, not cloned; cloning needs multiple groups in defaultGroup. useACK makes the forwarder hold data until the receiving indexer confirms it was written."],

  // 6.1 Deployment server
  [D6, EASY, "What is the job of a deployment server?", "Distribute apps and configuration to groups of forwarders and other deployment clients", "Receive and index data from forwarders", "Authenticate users who sign in to Splunk Web", "Run scheduled searches on behalf of the search head", "A deployment server centrally manages the configuration of its clients by pushing apps to them. It does not index data or serve searches."],
  [D6, MEDIUM, "In a Splunk Cloud environment, where does the deployment server that manages on-premises forwarders run?", "On a customer-managed Splunk Enterprise instance in the customer's environment", "On the Splunk Cloud search head", "On the Splunk Cloud indexers", "On each universal forwarder", "Splunk Cloud does not host a deployment server for customer forwarders. The customer runs one on a Splunk Enterprise instance that can reach its forwarders on the management port."],
  [D6, HARD, "A deployment server pushes the app web_inputs to a forwarder, and an administrator then edits that app's inputs.conf directly on the forwarder. What happens at a later check-in?", "The deployment server's copy replaces the app, so the local edit is lost", "The forwarder uploads its edited copy back to the deployment server", "The deployment server stops managing that forwarder permanently", "Both versions are merged and the forwarder keeps both settings", "Deployment clients compare their apps with the server's copy and reinstall any app that differs. Changes to deployed apps must be made on the deployment server, or they will be overwritten."],
  // 6.2 Forwarder management UI
  [D6, EASY, "On the deployment server, where in Splunk Web can an administrator view deployment clients and manage server classes?", "Settings > Forwarder management (called Agent management in newer releases)", "Settings > Indexes", "Settings > Data inputs > Forwarded inputs", "Apps > Cloud Monitoring Console", "The forwarder management interface lists clients, server classes, and apps and lets administrators edit their mappings. Newer Splunk Enterprise versions rename it Agent management."],
  [D6, MEDIUM, "In forwarder management, a client's last phone home time is several hours old. What does this most likely indicate?", "The client is not checking in, for example because of a network problem or a wrong deployment server address", "The client has received every app and no longer needs to check in", "The client has been promoted to a heavy forwarder", "The deployment server has finished deploying all of its apps", "Deployment clients phone home on a short interval for as long as they are running. A stale time means the client cannot reach the server or is no longer running."],
  // 6.3 Deployment clients
  [D6, EASY, "Which configuration file on a forwarder points it to its deployment server?", "deploymentclient.conf", "outputs.conf", "serverclass.conf", "inputs.conf", "deploymentclient.conf sets targetUri, the deployment server's address and management port. serverclass.conf lives on the deployment server, and outputs.conf controls where data is sent."],
  [D6, MEDIUM, "Which command configures a forwarder as a deployment client of ds01 on the default management port?", "splunk set deploy-poll ds01:8089", "splunk add forward-server ds01:8089", "splunk add deploy-client ds01:9997", "splunk set default-hostname ds01", "set deploy-poll writes the deployment server address into deploymentclient.conf. add forward-server configures a data receiver, and 9997 is the data port rather than the management port."],
  [D6, MEDIUM, "What does the phone home interval of a deployment client control?", "How often the client contacts the deployment server to check for app changes", "How often the client sends data to the indexers", "How long the client keeps data in its output queue", "How often the client restarts splunkd", "The phoneHomeIntervalInSecs setting in deploymentclient.conf controls the check-in frequency. Data forwarding and restarts are governed by other settings."],
  // 6.4 Deployment apps and server classes
  [D6, MEDIUM, "On a deployment server, in which directory are apps placed so they can be deployed to clients?", "$SPLUNK_HOME/etc/deployment-apps", "$SPLUNK_HOME/etc/apps", "$SPLUNK_HOME/etc/system/local", "$SPLUNK_HOME/var/run/splunk/deploy", "Apps for clients are staged in etc/deployment-apps. Apps in etc/apps run on the deployment server itself and are not sent to clients."],
  [D6, HARD, "What does this serverclass.conf configuration do?\n[serverClass:linux_web]\nwhitelist.0 = web*\nmachineTypesFilter = linux-x86_64\n[serverClass:linux_web:app:web_inputs]\nrestartSplunkd = true", "Deploys web_inputs to clients whose names match web* and that run 64-bit Linux, then restarts splunkd on them", "Deploys web_inputs to every client except those whose names match web*", "Deploys web_inputs to all Linux clients and restarts the deployment server", "Creates a client named linux_web that runs web_inputs once", "A server class combines client filters with the apps to deploy. Here, the client must match both the name pattern and the machine type, and restartSplunkd restarts the client after the app is installed so its inputs take effect."],

  // 7.1 The input process
  [D7, EASY, "Which configuration file defines data inputs, such as monitored files, on a forwarder?", "inputs.conf", "outputs.conf", "props.conf", "indexes.conf", "inputs.conf defines what a forwarder collects. outputs.conf defines where it sends data, and props.conf controls how data is processed."],
  [D7, EASY, "Which inputs.conf stanza monitors the file /var/log/secure?", "[monitor:///var/log/secure]", "[file:/var/log/secure]", "[tail:///var/log/secure]", "[monitor:var/log/secure]", "Monitor stanzas use the monitor:// prefix followed by the absolute path, which produces three slashes on Linux. The other prefixes are not valid input types."],
  [D7, EASY, "By default, what value does Splunk assign to the source field for data read from a monitored file?", "The full path of the file", "The name of the forwarder", "The sourcetype name", "The index name", "For file inputs, source is the file's full path, such as /var/log/secure. The forwarder's name becomes the host field instead."],
  [D7, MEDIUM, "How does Splunk keep track of how far it has read into each monitored file?", "The fishbucket stores a checksum of each file's beginning and a seek pointer", "It saves a copy of each file in the index", "It renames each file after reading it", "It records file positions in outputs.conf", "The fishbucket records which files have been seen and how far they have been read, so monitoring resumes correctly after a restart. Files are not renamed or copied."],
  [D7, MEDIUM, "By default, how many bytes at the start of a monitored file does Splunk use to compute the checksum that identifies it?", "256", "64", "1024", "4096", "Splunk computes a CRC over the first 256 bytes by default, which initCrcLength can change. Files with identical first 256 bytes therefore look like the same file."],
  [D7, MEDIUM, "A log is rotated by renaming access.log to access.log.1 and starting a new access.log. Why does Splunk not re-index access.log.1 when both names match the monitor?", "Its checksum matches a file already recorded in the fishbucket, so Splunk knows the data was read", "Splunk ignores any file whose name ends in a number", "Rotated files are automatically sent to the nullQueue", "The forwarder deletes rotated files before reading them", "Splunk identifies files by content checksum rather than name, so a renamed file is recognized as already read. It continues from the saved position instead of starting over."],
  [D7, MEDIUM, "What does Splunk do when a monitor input encounters a .gz file?", "It decompresses the file and indexes its contents", "It indexes the compressed bytes as binary data", "It skips the file because compressed files are never supported", "It forwards the file to the indexer to decompress", "Splunk can read compressed archives such as gzip by decompressing them during input. This is one reason compressed copies of already-indexed logs can be indexed a second time."],
  [D7, HARD, "In a test environment, an administrator wants a forwarder to re-read a log file it has already fully indexed. What achieves this?", "Reset that file's fishbucket record, for example with splunk cmd btprobe --reset, and restart the forwarder", "Run splunk reload deploy-server", "Change the sourcetype in inputs.conf", "Delete the events in Splunk Cloud with the delete command", "Splunk will not re-read a file it has recorded as complete. Resetting the file's fishbucket entry clears that record; changing the sourcetype or deleting events does not affect the forwarder's tracking."],
  [D7, HARD, "Which input type indexes files placed in a directory once and then deletes them, instead of continuously watching them?", "[batch://<path>] with move_policy = sinkhole", "[monitor://<path>] with followTail = true", "[monitor://<path>] with recursive = false", "[script://<path>] with interval = 0", "Batch inputs with the sinkhole policy consume and remove files, which suits one-time loads. Monitor inputs never delete source files."],
  // 7.2 File and directory monitors
  [D7, EASY, "What happens when a monitor stanza points to a directory rather than a file?", "Splunk monitors the files in that directory, including files in its subdirectories", "Splunk monitors only the newest file in the directory", "Splunk reads only the directory listing", "The stanza is ignored because monitors must name a single file", "Directory monitors are recursive by default and pick up new files as they appear. recursive = false limits them to the top-level directory."],
  [D7, EASY, "Which command adds a monitor input for /var/log/app.log on a forwarder?", "splunk add monitor /var/log/app.log", "splunk add forward-server /var/log/app.log", "splunk install app /var/log/app.log", "splunk set deploy-poll /var/log/app.log", "add monitor creates a monitor stanza in inputs.conf. The other commands configure receivers, install apps, or set the deployment server."],
  [D7, EASY, "Which command lists the files and directories a forwarder is currently monitoring?", "splunk list monitor", "splunk list forward-server", "splunk show monitors", "splunk btool outputs list", "list monitor shows the monitored paths and files. list forward-server shows receivers, and btool outputs list shows forwarding configuration."],
  [D7, MEDIUM, "Which wildcard in a monitor path matches any number of directory levels?", "... (three dots)", "* (asterisk)", "? (question mark)", "** (two asterisks)", "The ellipsis wildcard recurses through any depth of directories. The asterisk matches only within a single path segment."],
  [D7, MEDIUM, "Can a Splunk Cloud administrator create a monitor input that reads log files from an on-premises Linux server directly from the Cloud stack?", "No; file monitors run on a forwarder installed where the files are, which sends the data to Splunk Cloud", "Yes; Splunk Cloud can mount any server's file system over the internet", "Yes; by adding the server's IP address to the IP allow list", "Only by opening a support case for each file", "A monitor input reads files on the machine where it runs. Files on customer servers are collected by forwarders on those servers or by forwarders that can read them."],
  [D7, MEDIUM, "Which inputs.conf setting stops a directory monitor from descending into subdirectories?", "recursive = false", "followTail = true", "crcSalt = <SOURCE>", "host_segment = 1", "Setting recursive to false limits the monitor to files directly in the named directory. The other settings control start position, file identity, and host naming."],
  [D7, MEDIUM, "What is the effect of followTail = true on a newly added monitor input?", "Splunk starts reading at the end of the file and ignores content that already exists", "Splunk reads the file from the beginning every time it changes", "Splunk monitors only the last line of the file", "Splunk follows symbolic links to other files", "followTail skips the existing contents on first read and indexes only new data. It is useful for very large existing logs whose history is not needed."],
  [D7, MEDIUM, "Which inputs.conf setting turns off a monitor input without removing its stanza?", "disabled = true", "index = nullQueue", "followTail = false", "recursive = false", "disabled = true stops the input while keeping the configuration for later. nullQueue is a queue used by transforms, not a valid index name."],
  [D7, HARD, "Which file does this stanza monitor?\n[monitor:///var/log/*/app.log]", "/var/log/web/app.log", "/var/log/web/old/app.log", "/var/log/app.log", "/var/log/web/app.log.1", "The asterisk matches exactly one path segment, so only app.log one directory below /var/log matches. A deeper path would need the ... wildcard, and app.log.1 does not match the file name."],
  [D7, HARD, "A monitor uses [monitor:///opt/app/logs] and the application compresses yesterday's log into a .gz file each night. Daily events now appear twice. What is the cause and fix?", "The compressed files have new checksums and are read again; add blacklist = \\.gz$ to the stanza", "The forwarder clock is wrong; set TZ on the forwarder", "Indexer acknowledgment duplicates every event; set useACK = false", "The fishbucket is full; increase initCrcLength", "Compression changes the file's bytes, so Splunk sees the .gz file as new and indexes its contents again. Excluding compressed files from the monitor prevents the duplicates."],
  // 7.3 Optional monitor settings
  [D7, EASY, "Which inputs.conf setting assigns a sourcetype to data collected by a monitor input?", "sourcetype", "source", "host", "index", "Setting sourcetype explicitly in the input avoids relying on automatic sourcetype detection. The source setting overrides the source field instead."],
  [D7, EASY, "Which inputs.conf setting sends a monitor input's data to a specific index?", "index", "sourcetype", "_TCP_ROUTING", "queue", "The index setting names the destination index, which must already exist in Splunk Cloud. _TCP_ROUTING selects an output group, not an index."],
  [D7, EASY, "What does ignoreOlderThan = 7d do in a monitor stanza?", "Skips files whose modification time is more than seven days old", "Deletes files older than seven days", "Keeps indexed events for seven days", "Re-reads files every seven days", "ignoreOlderThan prevents a monitor from processing old, inactive files based on modification time. It does not delete files or change index retention."],
  [D7, MEDIUM, "A directory contains many file types. Which setting limits a monitor of that directory to files ending in .log?", "whitelist = \\.log$", "blacklist = \\.log$", "sourcetype = log", "crcSalt = .log", "The whitelist keeps only files whose paths match the regular expression. A blacklist with the same pattern would do the opposite and exclude the .log files."],
  [D7, MEDIUM, "How are the whitelist and blacklist values of a monitor stanza interpreted?", "As regular expressions matched against each file's full path", "As shell wildcards matched against the file name only", "As exact file names", "As lists of sourcetypes", "Both settings are regular expressions applied to the full path. A pattern written as a shell glob, such as *.log, will not behave as expected."],
  [D7, MEDIUM, "Files are written to /logs/web01/access.log and /logs/web02/access.log. Which setting sets the host field to web01 or web02?", "host_segment = 2", "host_segment = 1", "host_segment = 3", "host = web*", "host_segment counts path segments from the root, so logs is 1 and web01 is 2. A literal host value with a wildcard is not expanded."],
  [D7, MEDIUM, "Which monitor setting extracts the host value from the file path with a regular expression?", "host_regex", "host_segment", "connection_host", "hostname_filter", "host_regex uses the first capture group of a regular expression applied to the path. host_segment uses a position, and connection_host applies to network inputs."],
  [D7, MEDIUM, "What does crcSalt = <SOURCE> do in a monitor stanza?", "Adds the file's full path to its checksum, so files with identical beginnings are treated as different files", "Encrypts the file contents before forwarding", "Adds a random value to every event", "Forces the file to be re-indexed after each restart", "Including the path in the checksum distinguishes files that start with the same bytes. The literal string <SOURCE> must be used exactly."],
  [D7, MEDIUM, "Which monitor setting sends a single input's data to a specific output group defined in outputs.conf?", "_TCP_ROUTING", "index", "queue", "defaultGroup", "_TCP_ROUTING lets one input override the forwarder's default output group. defaultGroup is set in outputs.conf and applies to every input that does not override it."],
  [D7, HARD, "Hundreds of small files in a monitored directory begin with the same 300-byte header, and only some of them are indexed. Which change addresses this?", "Set crcSalt = <SOURCE> or raise initCrcLength so each file has a unique checksum", "Set followTail = true so files are read from the end", "Set recursive = false so subdirectories are ignored", "Set ignoreOlderThan = 1d so only recent files are read", "Files with identical first bytes produce the same checksum, so Splunk treats them as one file it has already seen. Salting the checksum with the path, or hashing more bytes, makes them distinct."],
  [D7, HARD, "Why can crcSalt = <SOURCE> cause duplicate events with logs that are rotated by renaming?", "A renamed file has a new path, so its salted checksum is new and Splunk reads it again", "The salt makes Splunk ignore the fishbucket entirely", "The salt disables indexer acknowledgment", "The salt causes every event to be sent to two indexers", "With the path in the checksum, a file renamed by rotation looks like a new file. This is why crcSalt should be avoided for inputs with rename-based rotation."],

  // 8.1 TCP and UDP inputs
  [D8, EASY, "Which inputs.conf stanza listens for syslog messages on UDP port 514?", "[udp://514]", "[tcp://514]", "[syslog://514]", "[splunktcp://514]", "UDP network inputs use the udp:// prefix and the port number. There is no syslog:// input type, and splunktcp is for data from Splunk forwarders."],
  [D8, MEDIUM, "What is the difference between a [tcp://9514] input and a [splunktcp://9997] input?", "tcp:// receives raw network data from any sender, while splunktcp:// receives data from Splunk forwarders", "tcp:// is encrypted, while splunktcp:// is plain text", "tcp:// is used only on Windows, while splunktcp:// is used only on Linux", "There is no difference; both names are interchangeable", "splunktcp inputs understand the Splunk-to-Splunk protocol that forwarders use. A plain tcp input treats whatever arrives as raw data, which suits devices that send logs over TCP."],
  [D8, MEDIUM, "Why do Splunk best practices recommend sending syslog to a dedicated syslog server whose files a forwarder monitors, rather than straight to a Splunk UDP input?", "UDP messages sent while Splunk is restarting or down are lost, whereas a syslog server writes them to disk for the forwarder to read", "Splunk cannot parse syslog data received over UDP", "UDP inputs are not allowed on universal forwarders", "Monitored files are indexed without counting against the license", "UDP has no delivery guarantee, so anything sent during a forwarder restart disappears. A syslog server buffers to files, and the forwarder's file tracking lets it catch up without loss."],
  [D8, HARD, "A [udp://514] input on a Linux forwarder that runs as a non-root user receives no data, although packets reach the host. What is the most likely cause?", "Ports below 1024 require root privileges, so the forwarder cannot bind to port 514", "UDP inputs only work on heavy forwarders", "Port 514 is reserved for Splunk-to-Splunk traffic", "The forwarder must have indexer acknowledgment enabled for UDP", "Linux restricts privileged ports to root. Common fixes are to listen on a port above 1024 and redirect traffic to it, or to use a syslog server that writes to files."],
  // 8.2 Basic scripted inputs
  [D8, EASY, "Where should the script used by a scripted input be placed?", "In the bin directory of the app that defines the input", "In $SPLUNK_HOME/etc/system/default", "In the index's data directory", "In the deployment server's etc/apps directory", "Scripted inputs run scripts from an app's bin directory, which keeps the script packaged with its configuration. system/default must never be modified."],
  [D8, MEDIUM, "What does Splunk index from a scripted input?", "Whatever the script writes to standard output", "The script's source code", "Only the script's exit code", "Whatever the script writes to its own log file", "Splunk captures the standard output of each run and indexes it as events. Writing to a separate file would require another input to collect it."],
  [D8, MEDIUM, "What does the interval setting do in this stanza?\n[script://./bin/check_disk.sh]\ninterval = 300", "Runs the script every 300 seconds", "Stops the script after it has run for 300 seconds", "Keeps the script's output for 300 days", "Waits 300 seconds before the first run only", "interval sets how often a scripted input runs, either in seconds or as a cron schedule. It does not control timeouts or retention."],
  // 8.3 Optional network input settings
  [D8, EASY, "On a network input, what does connection_host = dns do?", "Sets the host field to the DNS name of the sending device", "Resolves the destination index from DNS", "Blocks senders that have no DNS record", "Sends the data to a DNS server", "connection_host decides how the host field is set for network data. dns uses a reverse lookup of the sender, ip uses its address, and none uses the configured host value."],
  [D8, MEDIUM, "What does the acceptFrom setting do on a network input?", "Limits which source addresses or networks may send data to the input", "Sets the sourcetype based on the sender", "Encrypts data from the listed senders", "Forwards data from the listed senders to a second indexer", "acceptFrom is an access list for network inputs. Connections from addresses that do not match are rejected."],
  [D8, MEDIUM, "What does persistentQueueSize do on a network input?", "Buffers data to disk when the in-memory queue is full, reducing data loss while output is blocked", "Sets the maximum size of a single event", "Limits how long data is kept in the index", "Controls how many senders may connect at once", "A persistent queue stores incoming data on disk when it cannot be forwarded fast enough. It helps with temporary output problems but does not replace a reliable collection design."],
  [D8, HARD, "A UDP input has acceptFrom = 10.1.1.0/24, !10.1.1.5. Is data from 10.1.1.5 accepted?", "Yes; the rules are checked in order and 10.1.1.5 matches the first rule, so it is accepted", "No; deny rules always take precedence over allow rules", "No; any address listed with ! is always rejected", "Yes, but only after the forwarder is restarted twice", "acceptFrom applies the first rule that matches. To block 10.1.1.5 while allowing the rest of the subnet, the !10.1.1.5 rule must come first."],
  // 8.4 Windows input types
  [D8, EASY, "Which inputs.conf stanza collects the Windows Security event log?", "[WinEventLog://Security]", "[perfmon://Security]", "[WinRegMon://Security]", "[monitor://Security]", "WinEventLog inputs read Windows event log channels by name. perfmon collects performance counters, and WinRegMon watches the registry."],
  [D8, EASY, "Which Windows input type collects performance counters such as processor utilization?", "perfmon", "WinEventLog", "WinHostMon", "admon", "perfmon inputs collect counters for performance objects at a set interval. WinHostMon gathers host inventory, and admon monitors Active Directory."],
  [D8, MEDIUM, "Which Windows input type detects changes to registry keys?", "WinRegMon", "WinEventLog", "WinNetMon", "WinPrintMon", "WinRegMon reports registry activity such as key creation and value changes. WinNetMon covers network activity and WinPrintMon covers printing."],
  [D8, HARD, "Which Windows input type records changes to Active Directory objects from a domain controller?", "admon", "WinHostMon", "perfmon", "WinRegMon", "The admon input monitors Active Directory and reports object changes. WinHostMon reports local host details such as installed software, not directory changes."],
  // 8.5 HTTP Event Collector
  [D8, EASY, "How does a client authenticate when sending data to the HTTP Event Collector?", "It sends a HEC token in the Authorization header, in the form Splunk <token>", "It signs in with a Splunk username and password on each request", "It presents the forwarder credentials package", "It needs no authentication when HTTPS is used", "HEC uses tokens rather than user accounts. Each token also determines the default index and sourcetype and which indexes the client may write to."],
  [D8, MEDIUM, "Which HEC endpoint accepts JSON objects with keys such as event, time, host, and sourcetype?", "/services/collector/event", "/services/collector/raw", "/services/collector/health", "/services/receivers/simple", "The event endpoint takes structured JSON in which each object is one event with optional metadata. The raw endpoint takes unformatted text instead."],
  [D8, MEDIUM, "Which HEC endpoint accepts plain text that Splunk then breaks into events using the sourcetype's line-breaking rules?", "/services/collector/raw", "/services/collector/event", "/services/collector/ack", "/services/collector/health", "The raw endpoint sends the payload through normal parsing, including line breaking and timestamp extraction. The ack and health endpoints do not accept event data."],
  [D8, MEDIUM, "A HEC token allows only the indexes main and web. A client sends an event that specifies index security. What happens?", "HEC rejects the event because the token does not allow that index", "The event is written to the security index anyway", "The event is silently written to main", "The token is disabled automatically", "A token can write only to its allowed indexes, so requests naming other indexes return an error. This lets administrators scope each token to the data it should produce."],
  [D8, HARD, "A HEC token has indexer acknowledgment enabled. What must a client do?", "Send a channel identifier with its requests and poll the ack endpoint with the returned ack IDs", "Wait for Splunk to send an email confirmation", "Use the raw endpoint, because acknowledgment does not work with the event endpoint", "Send each event twice and compare the responses", "With acknowledgment, the client identifies a channel, for example with the X-Splunk-Request-Channel header, and then checks /services/collector/ack to confirm indexing. Acknowledgment works with both the event and raw endpoints."],

  // 9.1 Default input-phase processing
  [D9, EASY, "Which of these happens during the input phase, before parsing?", "Assigning source, sourcetype, host, and index metadata", "Breaking the data into events", "Extracting timestamps", "Applying SEDCMD replacements", "The input phase reads the data and attaches its metadata. Line breaking, timestamp extraction, and SEDCMD happen later in the parsing phase."],
  [D9, MEDIUM, "Which props.conf settings take effect on a universal forwarder as part of the input phase?", "CHARSET and rules that assign a sourcetype, such as a [source::...] stanza with sourcetype =", "LINE_BREAKER and SHOULD_LINEMERGE", "TIME_PREFIX and TIME_FORMAT", "TRANSFORMS- and SEDCMD-", "Input-phase props settings such as character set and sourcetype assignment run where the data is read. Line breaking, timestamps, and transforms run where the data is parsed, which for unstructured universal forwarder data is Splunk Cloud or a heavy forwarder."],
  [D9, MEDIUM, "What does Splunk do by default with a monitored file that it determines to be binary?", "Skips it, unless NO_BINARY_CHECK = true is set for that data", "Indexes it as base64 text", "Converts it to UTF-8 and indexes it", "Sends it to the nullQueue and counts it against the license", "Splunk checks for binary content and ignores binary files to avoid indexing meaningless data. NO_BINARY_CHECK overrides that check when the data is actually wanted."],
  [D9, HARD, "A monitored file has no sourcetype in inputs.conf and matches no props.conf rule. What does Splunk do?", "It tries to recognize the format automatically and, failing that, generates a sourcetype based on the file name", "It refuses to index the file until a sourcetype is set", "It assigns the sourcetype syslog to all unknown data", "It uses the index name as the sourcetype", "Automatic sourcetyping can lead to inconsistent names across hosts. Setting the sourcetype explicitly in the input avoids that unpredictability."],
  // 9.2 Fine-tuning sourcetypes and character set encoding
  [D9, EASY, "Which props.conf setting specifies the character encoding of incoming data?", "CHARSET", "ENCODING", "SEDCMD", "TRUNCATE", "CHARSET tells Splunk how to decode the bytes it reads. ENCODING is not a valid props.conf setting."],
  [D9, EASY, "Which character encoding does Splunk assume when no CHARSET is set?", "UTF-8", "ASCII only", "UTF-16", "ISO-8859-1", "Splunk treats input as UTF-8 by default. Data in another encoding needs CHARSET so that non-ASCII characters are not garbled."],
  [D9, MEDIUM, "What does CHARSET = AUTO do?", "Tells Splunk to detect the character encoding automatically", "Converts all data to ASCII", "Removes characters that are not printable", "Uses the encoding of the indexer's operating system", "AUTO lets Splunk guess the encoding of each source. Setting the actual encoding explicitly is more reliable when it is known."],
  [D9, MEDIUM, "Logs written in Shift-JIS appear garbled in Splunk Cloud. Where should CHARSET = SHIFT-JIS be configured?", "In props.conf for that source or sourcetype on the forwarder that reads the files", "In indexes.conf on the Splunk Cloud indexers", "In the user's Splunk Web preferences", "In transforms.conf with DEST_KEY = _raw", "CHARSET is applied in the input phase, so it must be set where the data is first read. Display preferences cannot repair data that was decoded incorrectly."],
  [D9, MEDIUM, "Which props.conf stanza assigns the sourcetype custom_app to every .log file under /var/log/custom?", "[source::/var/log/custom/*.log]\nsourcetype = custom_app", "[custom_app]\nsource = /var/log/custom/*.log", "[host::/var/log/custom/*.log]\nsourcetype = custom_app", "[sourcetype::custom_app]\npath = /var/log/custom/*.log", "A source:: stanza matches data by path and can set the sourcetype. A sourcetype-named stanza applies settings to data that already has that sourcetype, so it cannot assign it."],
  [D9, HARD, "props.conf sets the same attribute in [mysourcetype], [host::web01], and [source::/var/log/app.log]. Which stanza's value applies to an event that matches all three?", "[source::/var/log/app.log]", "[host::web01]", "[mysourcetype]", "Whichever stanza appears first in the file", "For matching stanzas, source settings override host settings, which override sourcetype settings. Order within the file does not decide between these stanza types."],

  // 10.1 Default parsing
  [D10, EASY, "Which tasks happen during the parsing phase?", "Breaking data into events, extracting timestamps, and applying index-time transforms", "Running scheduled searches and alerts", "Extracting search-time fields and applying lookups", "Authenticating forwarders and users", "Parsing turns the incoming stream into individual, timestamped events and applies index-time changes. Search-time extraction and lookups happen later, when users search."],
  [D10, EASY, "A universal forwarder sends unstructured log data directly to Splunk Cloud. Where is that data parsed?", "On the Splunk Cloud indexers", "On the universal forwarder", "On the deployment server", "On the user's browser at search time", "A universal forwarder sends unstructured data unparsed, so the Cloud indexing tier parses it. Parsing settings for that data must therefore be deployed to Splunk Cloud."],
  [D10, MEDIUM, "With default settings, how does Splunk turn incoming lines into events?", "It splits the data at newlines and then merges lines into events, starting a new event at lines that contain a date", "It treats the entire file as one event", "It starts a new event every 256 bytes", "It starts a new event only at blank lines", "By default, LINE_BREAKER splits on newlines and SHOULD_LINEMERGE = true reassembles lines, using BREAK_ONLY_BEFORE_DATE to find event starts. This works for many logs but is slower than explicit line breaking."],
  [D10, MEDIUM, "How can a Splunk Cloud administrator deploy line-breaking and timestamp settings for a custom sourcetype?", "Create or edit the sourcetype under Settings > Source types, or upload a private app that contains props.conf", "Edit props.conf on the Cloud indexers over SSH", "Add the settings to inputs.conf on the search head", "Ask users to set them in their search preferences", "Splunk Web's source type editor and private apps are the supported ways to deliver props.conf to Splunk Cloud. Customers cannot edit files on the indexers."],
  // 10.2 Line breaking
  [D10, EASY, "What does SHOULD_LINEMERGE = false do?", "Makes each LINE_BREAKER match end an event, with no merging of lines afterward", "Merges every line in the file into one event", "Stops Splunk from breaking events at all", "Removes blank lines from events", "With line merging off, events are defined entirely by LINE_BREAKER. This is faster and more predictable than merging lines after the fact."],
  [D10, MEDIUM, "For multiline events, which configuration does Splunk recommend for the best parsing performance?", "SHOULD_LINEMERGE = false with a LINE_BREAKER regex that matches the boundary between events", "SHOULD_LINEMERGE = true with BREAK_ONLY_BEFORE_DATE = true", "SHOULD_LINEMERGE = true with MAX_EVENTS = 1", "TRUNCATE = 0 with no LINE_BREAKER", "Defining event boundaries directly with LINE_BREAKER avoids the extra line-merging step. Line merging works but costs more processing on high-volume data."],
  [D10, MEDIUM, "In a LINE_BREAKER regular expression, what happens to the text matched by the first capturing group?", "It is treated as the boundary between events and discarded", "It becomes the first line of the next event", "It is saved as an indexed field", "It is used as the event's timestamp", "LINE_BREAKER must contain a capturing group, and whatever that group matches is removed as the delimiter. Text outside the group stays with the events."],
  [D10, MEDIUM, "With SHOULD_LINEMERGE = true and BREAK_ONLY_BEFORE = ^\\d{4}-\\d{2}-\\d{2}, where does a new event begin?", "Only at lines that start with a date such as 2026-10-13", "At every line", "Only at blank lines", "Only after 256 lines", "BREAK_ONLY_BEFORE starts a new event when a line matches the pattern, so lines without a leading date are merged into the previous event. This suits logs with multiline stack traces."],
  [D10, HARD, "Events look like this:\n2026-10-01 12:00:01 ERROR Failed request\n  at handler line 10\n  at server line 42\n2026-10-01 12:00:02 INFO Recovered\nWith SHOULD_LINEMERGE = false, which LINE_BREAKER keeps the indented lines with their event?", "([\\r\\n]+)\\d{4}-\\d{2}-\\d{2}", "([\\r\\n]+)", "(\\d{4}-\\d{2}-\\d{2})", "([\\r\\n]+)\\s+at", "Only newlines followed by a date mark a new event, and the date is outside the capturing group so it stays in the event. Capturing the date itself would discard it, and breaking on every newline splits the stack trace."],
  [D10, HARD, "Large JSON events are cut off partway through, and the rest of each object appears as separate, malformed events. Which setting most likely needs to be raised?", "TRUNCATE", "MAX_DAYS_AGO", "MAX_TIMESTAMP_LOOKAHEAD", "autoLBFrequency", "Events longer than TRUNCATE, 10,000 bytes by default, are cut, and the remainder can end up as separate events. Raising TRUNCATE for that sourcetype keeps the objects whole."],
  // 10.3 Timestamps and time zones
  [D10, EASY, "Which props.conf setting gives the strptime pattern that describes an event's timestamp?", "TIME_FORMAT", "TIME_PREFIX", "TZ", "DATETIME_CONFIG", "TIME_FORMAT describes how the timestamp is written. TIME_PREFIX locates it and TZ assigns a time zone."],
  [D10, MEDIUM, "What does TIME_PREFIX do?", "Defines a regex matching the text that comes immediately before the timestamp", "Adds a prefix to every timestamp", "Sets the time zone of the timestamp", "Sets the number of characters to scan for a timestamp", "Splunk starts looking for the timestamp right after the TIME_PREFIX match. This prevents other dates in the event from being mistaken for the event time."],
  [D10, MEDIUM, "What does MAX_TIMESTAMP_LOOKAHEAD control?", "How many characters past the TIME_PREFIX match, or the start of the event, Splunk scans for a timestamp", "How many days in the future a timestamp may be", "How many events Splunk reads before guessing a format", "How long Splunk waits for a delayed event", "Limiting the lookahead keeps Splunk from matching a later date in the event and speeds up timestamp recognition. Future-date limits are controlled by MAX_DAYS_HENCE instead."],
  [D10, MEDIUM, "Which TIME_FORMAT matches the timestamp 2026-10-13 14:05:09.123?", "%Y-%m-%d %H:%M:%S.%3N", "%d-%m-%Y %H:%M:%S.%3N", "%Y-%m-%d %I:%M:%S %p", "%Y-%d-%m %H:%M:%S", "%Y-%m-%d matches the year, month, and day order, %H is a 24-hour hour, and %3N matches three subsecond digits. The other patterns have the wrong field order or a 12-hour clock."],
  [D10, HARD, "Raw timestamps from servers in New York contain no time zone, and the events are indexed several hours off. What fixes this for new data?", "Set TZ = America/New_York for those hosts or that sourcetype in props.conf where the data is parsed", "Change the time zone in each user's Splunk Web preferences", "Set MAX_DAYS_AGO = 1 in props.conf", "Change the forwarder's outputs.conf to use UTC", "TZ tells Splunk which zone to apply when the timestamp does not state one. User preferences only change how times are displayed, and already-indexed events keep their stored time."],
  [D10, HARD, "An event's timestamp includes the offset -0700, and props.conf for its sourcetype sets TZ = UTC. Which time zone does Splunk use for that event?", "The -0700 offset in the event, because a zone in the raw timestamp takes precedence over TZ", "UTC, because TZ always overrides the event", "The forwarder host's local zone", "The search head's time zone", "Splunk applies TZ only when the raw timestamp does not specify a zone. Explicit offsets in the data are honored."],
  // 10.4 Data Preview
  [D10, EASY, "In the Add Data workflow, which step shows how Splunk will break and timestamp a sample file before anything is indexed?", "The Set Source Type step (data preview)", "The Review step", "The Input Settings step", "The Done step", "The Set Source Type page previews events using the current settings, so line breaking and timestamps can be fixed before indexing. The later steps choose the index and confirm the input."],
  [D10, EASY, "In data preview, which section of settings controls how lines are grouped into events?", "Event Breaks", "Timestamp", "Index", "App context", "Event Breaks offers automatic, every-line, or regex-based breaking. The Timestamp section handles timestamp extraction."],
  [D10, MEDIUM, "After correcting line breaking and timestamps in data preview, how does an administrator reuse the settings for future data?", "Save them as a new source type", "Export the preview as a CSV file", "Copy them into the user's preferences", "Schedule a search that re-applies them", "Saving creates a sourcetype that holds the props.conf settings so later inputs can use it. Previews themselves are not stored."],
  [D10, MEDIUM, "Why should an administrator check sample data with data preview, or in a test index, before onboarding a new production source?", "Line breaking and timestamps are fixed when data is indexed, so mistakes cannot be corrected without re-indexing", "Data preview indexes the data at no license cost", "Data preview is the only way to create an index", "Production indexes cannot be searched until data is previewed", "Index-time decisions are permanent for each event. Validating them on sample data first avoids polluting production indexes with badly parsed events."],

  // 11.1 Defining and invoking transformations
  [D11, EASY, "Which configuration file holds transform stanzas that contain REGEX, DEST_KEY, and FORMAT?", "transforms.conf", "props.conf", "inputs.conf", "outputs.conf", "transforms.conf defines what a transformation does. props.conf decides which data the transformation applies to."],
  [D11, EASY, "Which props.conf attribute invokes an index-time transformation for a sourcetype?", "TRANSFORMS-<class> = <transform_stanza>", "REPORT-<class> = <transform_stanza>", "EXTRACT-<class> = <regex>", "LOOKUP-<class> = <lookup>", "TRANSFORMS- runs transforms during parsing. REPORT-, EXTRACT-, and LOOKUP- are search-time settings."],
  [D11, MEDIUM, "In props.conf, TRANSFORMS-cleanup = t_one, t_two. In what order do the transforms run?", "t_one, then t_two, in the order listed", "t_two first, because the last one wins", "In alphabetical order of the stanza names", "In parallel, with no defined order", "Transforms in one TRANSFORMS- list run from left to right, and later ones see the result of earlier ones. This is what makes the nullQueue-then-indexQueue filtering pattern work."],
  [D11, MEDIUM, "Universal forwarders send unstructured data directly to Splunk Cloud. Where must index-time transforms for that data be deployed?", "To Splunk Cloud, for example in a private app", "To the universal forwarders", "To the deployment server only", "To users' search-time knowledge objects", "Index-time transforms run where data is parsed, which is the Cloud indexing tier for this data. On a universal forwarder they would have no effect."],
  [D11, HARD, "How do REPORT-<class> and TRANSFORMS-<class> in props.conf differ?", "REPORT- performs search-time field extraction using a transforms.conf stanza, while TRANSFORMS- changes data at index time", "REPORT- runs at index time, while TRANSFORMS- runs at search time", "REPORT- creates reports, while TRANSFORMS- creates dashboards", "They are synonyms and behave identically", "Both reference stanzas in transforms.conf, but at different stages. REPORT- extractions can change at any time, while TRANSFORMS- results are fixed when the data is indexed."],
  // 11.2 props.conf and transforms.conf: routing, overrides, and masking
  [D11, EASY, "Which transforms.conf settings discard matching events before they are indexed?", "DEST_KEY = queue and FORMAT = nullQueue", "DEST_KEY = _raw and FORMAT = nullQueue", "DEST_KEY = queue and FORMAT = indexQueue", "DEST_KEY = _MetaData:Index and FORMAT = null", "Routing an event to the nullQueue drops it during parsing. indexQueue keeps the event, and there is no index named null."],
  [D11, EASY, "Which DEST_KEY changes the index that an event is written to?", "_MetaData:Index", "MetaData:Sourcetype", "MetaData:Host", "_raw", "Setting DEST_KEY = _MetaData:Index with FORMAT = <index name> routes matching events to another index. The other keys change the sourcetype, host, or raw text."],
  [D11, MEDIUM, "Which transforms.conf settings change matching events' sourcetype to app_errors?", "DEST_KEY = MetaData:Sourcetype and FORMAT = sourcetype::app_errors", "DEST_KEY = MetaData:Sourcetype and FORMAT = app_errors", "DEST_KEY = _MetaData:Index and FORMAT = app_errors", "DEST_KEY = _raw and FORMAT = sourcetype=app_errors", "Sourcetype overrides require the sourcetype:: prefix in FORMAT. Without the prefix the value is not applied as intended."],
  [D11, MEDIUM, "A transform with DEST_KEY = MetaData:Host should set the host to the first capture group of its REGEX. What should FORMAT be?", "host::$1", "$1", "host=$1", "_host::$1", "Host overrides use the host:: prefix, and $1 refers to the first capture group. The same prefix style is used for source:: and sourcetype::."],
  [D11, MEDIUM, "What does this configuration do?\ntransforms.conf\n[drop_debug]\nREGEX = \\sDEBUG\\s\nDEST_KEY = queue\nFORMAT = nullQueue\nprops.conf\n[app_logs]\nTRANSFORMS-drop = drop_debug", "Discards app_logs events that contain DEBUG before they are indexed", "Indexes only the DEBUG events from app_logs", "Masks the word DEBUG in app_logs events", "Moves DEBUG events into a separate index", "Events that match the regex are routed to the nullQueue and never written. Other app_logs events are indexed normally."],
  [D11, MEDIUM, "Which DEST_KEY lets a transform rewrite the text of an event, for example to mask data?", "_raw", "queue", "_MetaData:Index", "MetaData:Source", "With DEST_KEY = _raw, FORMAT replaces the event text, usually using capture groups to keep the parts that should remain. The other keys change routing or metadata."],
  [D11, MEDIUM, "Do events routed to the nullQueue count against the ingest license?", "No; they are discarded before indexing, so they do not count", "Yes; all data received counts in full", "Yes, but at half the normal rate", "Only if they came from a universal forwarder", "License usage is measured on data written to indexes. Filtering unwanted events with the nullQueue is a common way to reduce ingest volume."],
  [D11, MEDIUM, "Firewall events that contain action=blocked must go to the security index. Which transforms.conf stanza does this?", "REGEX = action=blocked\nDEST_KEY = _MetaData:Index\nFORMAT = security", "REGEX = action=blocked\nDEST_KEY = queue\nFORMAT = security", "REGEX = action=blocked\nDEST_KEY = _raw\nFORMAT = index=security", "REGEX = security\nDEST_KEY = _MetaData:Index\nFORMAT = action=blocked", "_MetaData:Index with FORMAT set to the index name routes matching events. The security index must exist, and the transform must be referenced from props.conf."],
  [D11, HARD, "Which configuration indexes only events containing ERROR and discards everything else for the sourcetype?", "TRANSFORMS-filter = setnull, keep_errors\n[setnull] REGEX = . sends everything to the nullQueue\n[keep_errors] REGEX = ERROR sends matches to the indexQueue", "TRANSFORMS-filter = keep_errors, setnull with the same two stanzas", "TRANSFORMS-filter = keep_errors only, with [keep_errors] REGEX = ERROR sending matches to the indexQueue", "TRANSFORMS-filter = setnull only, with [setnull] REGEX = ERROR sending matches to the nullQueue", "Order matters: first send every event to the nullQueue, then send the ERROR events back to the indexQueue. Reversing the order would discard everything, and keep_errors alone does not drop the other events."],
  [D11, HARD, "Given this transform, how is the event user=bob ssn=123-45-6789 status=ok indexed?\nREGEX = ^(.*ssn=)\\d{3}-\\d{2}-(\\d{4}.*)$\nDEST_KEY = _raw\nFORMAT = $1xxx-xx-$2", "user=bob ssn=xxx-xx-6789 status=ok", "user=bob ssn=xxx-xx-xxxx status=ok", "xxx-xx-6789", "user=bob ssn=123-45-6789 status=ok", "$1 keeps everything up to ssn=, the literal xxx-xx- replaces the first five digits, and $2 keeps the last four digits and the rest of the event. The masked text replaces _raw permanently."],
  // 11.3 SEDCMD
  [D11, EASY, "What does a SEDCMD setting do?", "Applies a sed-style substitution to the event text at index time", "Runs a shell command on the forwarder", "Extracts a field at search time", "Sends events to a different index", "SEDCMD edits _raw during parsing, which makes it useful for masking or removing text. It does not run arbitrary commands."],
  [D11, EASY, "In which configuration file is SEDCMD defined?", "props.conf", "transforms.conf", "inputs.conf", "outputs.conf", "SEDCMD-<class> is set in a props.conf stanza for a sourcetype, source, or host. Unlike TRANSFORMS-, it needs no matching stanza in transforms.conf."],
  [D11, MEDIUM, "How is card=4111111111111111 indexed with this setting?\nSEDCMD-cc = s/\\d{12}(\\d{4})/XXXXXXXXXXXX\\1/g", "card=XXXXXXXXXXXX1111", "card=4111111111111111", "card=XXXXXXXXXXXXXXXX", "card=411111111111XXXX", "The expression replaces the first twelve digits with X characters and puts back the captured last four with \\1. The original number is never written to the index."],
  [D11, MEDIUM, "What does the trailing g in SEDCMD-mask = s/secret=\\S+/secret=####/g do?", "Replaces every match in the event, not only the first", "Makes the match case-insensitive", "Applies the substitution at search time", "Writes a copy of the original event to another index", "As in sed, g means global replacement within the event. Without it, only the first occurrence would be masked."],
  [D11, HARD, "A SEDCMD mask is deployed only to universal forwarders that send unstructured data to Splunk Cloud, and the unmasked values still appear in searches. Why?", "SEDCMD runs in the parsing phase, which does not happen on a universal forwarder for this data; deploy it to Splunk Cloud or a heavy forwarder", "SEDCMD only works on Windows", "SEDCMD requires a matching stanza in transforms.conf", "SEDCMD is applied only to data sent over HEC", "Masking must be configured where parsing happens. Events that were already indexed unmasked also stay that way, so the fix applies only to new data."],

  // 12.1 Installing apps
  [D12, EASY, "What is Splunkbase?", "Splunk's catalog of apps and add-ons built by Splunk, partners, and the community", "The database that stores indexed events", "The command-line tool for managing Splunk Cloud", "The support portal for opening cases", "Splunkbase is where apps and add-ons are published and downloaded. Splunk Cloud administrators can install compatible Splunkbase apps directly from Splunk Web."],
  [D12, EASY, "Where in Splunk Web can a Splunk Cloud administrator browse Splunkbase and install apps?", "Apps > Find More Apps", "Settings > Indexes", "Settings > Forwarder management", "Search & Reporting > Datasets", "The app browser in Splunk Web lists the Splunkbase apps that can be installed on the stack. The other pages manage indexes, deployment clients, and datasets."],
  [D12, MEDIUM, "A Splunkbase app is not offered for installation from within Splunk Cloud. What is the most likely reason?", "The app has not been vetted as compatible with Splunk Cloud Platform", "The app is too large to download", "The administrator lacks the can_delete role", "Splunk Cloud cannot run any apps that contain dashboards", "Splunk Cloud only installs apps that have passed its compatibility vetting. Apps without that approval cannot be self-installed on the stack."],
  [D12, MEDIUM, "Which tool lets a Victoria Experience administrator install apps programmatically, for example from a deployment pipeline?", "The Admin Config Service (ACS)", "The deployment server", "splunk btool", "The HTTP Event Collector", "ACS exposes Splunk Cloud administration tasks, including app installation, through an API and CLI. A deployment server manages on-premises clients, not the Cloud stack."],
  // 12.2 Private apps and vetting
  [D12, EASY, "What is a private app in Splunk Cloud Platform?", "A custom app created by the customer and uploaded to its own stack rather than installed from Splunkbase", "An app that only one user is allowed to open", "A Splunkbase app that has been hidden", "An app that runs only on forwarders", "Private apps package a customer's own configuration and knowledge objects. They are uploaded to the stack and must pass vetting before installation."],
  [D12, MEDIUM, "Which Splunk tool checks an app package against Splunk Cloud requirements before it is uploaded?", "Splunk AppInspect", "splunk btool", "splunk diag", "The Cloud Monitoring Console", "AppInspect runs automated checks that Splunk Cloud vetting also uses. Running it first finds problems before the upload is rejected."],
  [D12, HARD, "A private app upload to Splunk Cloud fails vetting. What should the administrator do?", "Review the failed checks in the vetting report, fix the app, repackage it, and upload it again", "Ask Splunk Support to install the app without vetting", "Publish the app to Splunkbase so it skips vetting", "Copy the app's files onto the Cloud indexers manually", "Vetting protects the shared platform, so failed checks have to be fixed in the app itself. Customers have no file access to the stack, and Splunkbase apps are also vetted."],
  // 12.3 Managing apps
  [D12, MEDIUM, "Which sharing level makes a knowledge object available to users in every app?", "All apps (global)", "This app only", "Private", "Owner only", "Global sharing exports the object to all apps, subject to role permissions. This app only keeps it inside its own app, and private limits it to its owner."],
  [D12, MEDIUM, "How can an administrator ensure that only members of the secops role can see a particular app?", "Edit the app's permissions in Manage Apps and grant read access only to secops", "Delete the app for every other user", "Move the app into a separate index", "Rename the app with a secops prefix", "App permissions set which roles can read and write the app. Indexes control data access and cannot hide an app."],
  [D12, HARD, "A newer version of an installed Splunkbase app is available. What happens to the administrator's customizations when the app is upgraded through Manage Apps?", "Settings in the app's local directory are preserved while the default directory is replaced", "All customizations are deleted and must be recreated", "The upgrade is blocked until all customizations are removed", "The new version is installed alongside the old one as a second app", "Upgrades replace the vendor-supplied default content and leave local changes in place. This is why customizations belong in local rather than default."],

  // 13.1 Isolating problems before contacting Support
  [D13, EASY, "Before opening a support case about data that is missing from a forwarder, what should the administrator do first?", "Check the forwarder's splunkd.log and Splunk Cloud's _internal index for errors", "Open a P1 case immediately", "Reinstall Splunk on every forwarder", "Delete and recreate the destination index", "Many data problems are caused by forwarder configuration, connectivity, or missing indexes and can be found in the logs. Gathering this evidence first either solves the problem or makes the case faster to resolve."],
  [D13, EASY, "Which index contains Splunk's own operational logs that are useful for troubleshooting?", "_internal", "_audit", "main", "summary", "_internal holds logs such as splunkd.log and metrics.log from Splunk instances, including forwarders. _audit records user and search activity."],
  [D13, MEDIUM, "Which search finds error messages from the splunkd log of the forwarder fwd01 in Splunk Cloud?", "index=_internal host=fwd01 sourcetype=splunkd log_level=ERROR", "index=_audit host=fwd01 action=error", "index=main host=fwd01 error", "| rest /services/server/info host=fwd01", "Forwarders send splunkd.log to _internal with the splunkd sourcetype and a log_level field. Searching main would only find application data that happens to contain the word error."],
  [D13, MEDIUM, "Without CLI access, how can a Splunk Cloud administrator view the configuration that applies on the search head, much as btool would show?", "Use the REST API, for example | rest /services/configs/conf-props", "Run splunk btool on the search head through SSH", "Download the configuration files from Splunkbase", "Use splunk list monitor from a forwarder", "The configs REST endpoints return the effective stanzas for each configuration file. Cloud customers have no SSH or CLI access to run btool on the stack."],
  [D13, MEDIUM, "Which search helps identify forwarders that have stopped sending data?", "| metadata type=hosts index=* and review each host's lastTime", "| rest /services/authentication/users", "index=_audit action=login", "| inputlookup forwarders.csv", "The metadata command reports the first and last event times for each host, so hosts whose last event is old stand out. The other searches cover users, logins, or a static lookup."],
  [D13, HARD, "A forwarder's internal logs reach Splunk Cloud, but its application data does not appear where expected. Which search shows whether that data is arriving with an unexpected index or sourcetype?", "| tstats count where index=* host=fwd01 by index, sourcetype", "index=main host=fwd01", "index=_internal host=fwd01 sourcetype=splunkd", "| rest /services/data/inputs/monitor", "Counting events for the host across all indexes and sourcetypes shows where the data actually landed. Searching only main or only _internal can miss data written somewhere unexpected."],
  // 13.2 Working with Splunk Cloud Support
  [D13, EASY, "Where do Splunk Cloud customers open a support case?", "Through the Splunk Support Portal", "By filing an issue on Splunkbase", "By emailing the stack's search head", "Through the Cloud Monitoring Console", "Cases are opened and tracked in the Splunk Support Portal. Splunkbase is for apps, and the Cloud Monitoring Console is a monitoring tool."],
  [D13, MEDIUM, "Which severity should be chosen for a support case when the production Splunk Cloud environment is unavailable to all users?", "P1 (critical)", "P2 (high)", "P3 (medium)", "P4 (low)", "P1 is reserved for critical production outages with no workaround. P4 is for general questions and minor issues."],
  [D13, MEDIUM, "Which information makes a support case about a parsing problem easiest to resolve?", "The stack name, affected sourcetype, sample events, time range, relevant props.conf settings, and any error messages", "Only the phrase 'data looks wrong'", "The administrator's Splunk password", "A screenshot of the Splunk Web home page", "Specific evidence lets Support reproduce and diagnose the issue quickly. Passwords should never be shared in a case."],
  [D13, HARD, "Splunk Support asks for a diag from an on-premises heavy forwarder. What should the administrator do?", "Run splunk diag on the forwarder and attach the resulting archive to the case", "Export a Cloud Monitoring Console dashboard as a PDF", "Send only the forwarder's outputs.conf file", "Give Support the forwarder's administrator credentials", "splunk diag collects the logs, configuration, and environment details that Support needs in one archive. It can be reviewed before sending, and sharing credentials is never required."],
];
